FUNCTION_BLOCK FB_S11
VAR_INPUT
    SensorCurrent : REAL;
    FallbackValue : REAL;
END_VAR
VAR_OUTPUT
    SensorValid : BOOL;
    DegradedMode : BOOL;
    ControlValue : REAL;
    AlarmLamp : BOOL;
    Status : WORD;
END_VAR
VAR
    initialized : BOOL := FALSE;
    FaultTimer : INT := 0;
    RecoverTimer : INT := 0;
    BlinkTimer : INT := 0;
    BlinkState : BOOL := FALSE;
END_VAR

IF NOT initialized THEN
    SensorValid := FALSE;
    DegradedMode := FALSE;
    ControlValue := 0.0;
    AlarmLamp := FALSE;
    Status := 16#0000;
    FaultTimer := 0;
    RecoverTimer := 0;
    BlinkTimer := 0;
    BlinkState := FALSE;
    initialized := TRUE;
ELSE
    (* 1. 传感器有效性滞回更新 *)
    IF SensorValid THEN
        IF (SensorCurrent < 3.6) OR (SensorCurrent > 21.0) THEN
            SensorValid := FALSE;
            FaultTimer := 0;
            RecoverTimer := 0;
        END_IF;
    ELSE
        IF (SensorCurrent >= 3.8) AND (SensorCurrent <= 20.5) THEN
            SensorValid := TRUE;
            FaultTimer := 0;
            RecoverTimer := 0;
        END_IF;
    END_IF;

    (* 2. 断线计时与进入降级 *)
    IF NOT SensorValid THEN
        IF NOT DegradedMode THEN
            IF FaultTimer >= 100 THEN
                DegradedMode := TRUE;
                RecoverTimer := 0;
            ELSE
                FaultTimer := FaultTimer + 1;
            END_IF;
        END_IF;
    ELSE
        FaultTimer := 0;
    END_IF;

    (* 3. 恢复计时与退出降级 *)
    IF DegradedMode THEN
        IF SensorValid THEN
            IF RecoverTimer >= 150 THEN
                DegradedMode := FALSE;
                RecoverTimer := 0;
            ELSE
                RecoverTimer := RecoverTimer + 1;
            END_IF;
        ELSE
            RecoverTimer := 0;
        END_IF;
    ELSE
        RecoverTimer := 0;
    END_IF;

    (* 4. 控制值输出 *)
    IF DegradedMode THEN
        ControlValue := FallbackValue;
    ELSIF SensorValid THEN
        ControlValue := (SensorCurrent - 4.0) / 16.0 * 100.0;
        IF ControlValue < 0.0 THEN
            ControlValue := 0.0;
        ELSIF ControlValue > 100.0 THEN
            ControlValue := 100.0;
        END_IF;
    END_IF;

    (* 5. 报警灯 *)
    IF DegradedMode THEN
        AlarmLamp := TRUE;
        BlinkTimer := 0;
        BlinkState := FALSE;
    ELSIF NOT SensorValid THEN
        IF BlinkTimer < 25 THEN
            BlinkTimer := BlinkTimer + 1;
        ELSE
            BlinkTimer := 0;
            BlinkState := NOT BlinkState;
        END_IF;
        AlarmLamp := BlinkState;
    ELSE
        AlarmLamp := FALSE;
        BlinkTimer := 0;
        BlinkState := FALSE;
    END_IF;

    (* 6. 状态码 *)
    IF DegradedMode THEN
        IF SensorValid THEN
            Status := 16#8A03;
        ELSE
            Status := 16#8A02;
        END_IF;
    ELSIF NOT SensorValid THEN
        Status := 16#8A01;
    ELSE
        Status := 16#0000;
    END_IF;
END_IF;
END_FUNCTION_BLOCK
